import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.file.*;import java.util.*;
import vn.rtr.aeris.control01.*;import vn.rtr.aeris.betaintegrated01.*;import vn.rtr.aeris.beta01runtime.*;import vn.rtr.aeris.native98.Dialect95;
public final class SessionQA {
 interface Op{void run()throws Exception;}static File root;static List<Map<String,Object>>results=new ArrayList<>();
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}static void denied(Op o,String s)throws Exception{boolean got=false;try{o.run();}catch(Exception e){got=true;}check(got,s);}static void test(String id,Op o){try{o.run();results.add(Values.map("id",id,"pass",true));}catch(Throwable e){results.add(Values.map("id",id,"pass",false,"error",e.toString()));}}
 static class Clock implements RunLifecycle.Clock {long n=1000000000L;public long monotonicNs(){return n;}public long wallUtcMs(){return 1700000000000L+n/1000000;}}
 static final String SOURCE="touch-11111111-1111-1111-1111-111111111111",PROV="ROOT_INJECTED_ANDROID_TOUCH";
 static final String H1=String.join("",Collections.nCopies(64,"1")),H2=String.join("",Collections.nCopies(64,"2")),H3=String.join("",Collections.nCopies(64,"3"));
 static byte[] p(int id){return new byte[Dialect95.D.get(id)[1]];}static ByteBuffer le(byte[]p){return ByteBuffer.wrap(p).order(ByteOrder.LITTLE_ENDIAN);}
 static String lines(File dir)throws Exception{StringBuilder s=new StringBuilder();File[]fs=dir.listFiles((d,n)->n.endsWith(".jsonl"));Arrays.sort(fs);for(File f:fs)s.append(new String(Files.readAllBytes(f.toPath()),"UTF-8"));return s.toString();}
 static class F {
  final Clock c=new Clock();final File dir;final RunLifecycle.Context context;final NativeSegments journal;final ControlSession s;final List<byte[]>sent=new ArrayList<>();boolean fg=true,failSend,stallIntent;int apseq,inputseq;int homeAlt=10000;
  F(String name,long duration)throws Exception{
   dir=new File(root,name);context=new RunLifecycle.Context(name,"epoch01","boot01","operator01","generation01","qa-profile");
   NativeSegments.Sync sync=new NativeSegments.Sync(){public void file(FileDescriptor fd)throws IOException{fd.sync();if(stallIntent)try{String l=lines(dir);if(l.substring(l.lastIndexOf('\n',l.length()-2)+1).contains("\"kind\":\"TX_INTENT\"")){stallIntent=false;c.n+=300000000L;}}catch(Exception e){throw new IOException(e);}}public void directory(File f)throws IOException{try(FileChannel d=FileChannel.open(f.toPath(),StandardOpenOption.READ)){d.force(true);}}};
   journal=new NativeSegments(dir,name,"epoch01",()->c.n,sync,32768,2L*1024*1024,128);
   ProviderDescriptor expected=new ProviderDescriptor(1,ProviderDescriptor.Mode.CANDIDATE_EXTERNAL,"qa-profile",H1,H2,H3,"tcp://10.0.2.2:5961","4.7.1");ProviderDescriptor.Observation observed=new ProviderDescriptor.Observation(1,ProviderDescriptor.Mode.CANDIDATE_EXTERNAL,"qa-profile",H1,H2,H3,"tcp://10.0.2.2:5961","4.7.1",true);
   s=new ControlSession(context,c,expected,observed,journal,()->fg,b->{if(failSend)throw new IOException("QA_UNKNOWN_SEND");sent.add(b.clone());},ProfileFixture.specs(),SOURCE,PROV,duration);ground();
  }
  void emit(int id,byte[]payload)throws Exception{byte[]b=Mavlink.packet(id,payload,(apseq++)&255);b[5]=42;b[6]=1;int length=b[1]&255,crc=Mavlink.crc(b,10+length,Dialect95.D.get(id)[2]);b[10+length]=(byte)crc;b[11+length]=(byte)(crc>>8);s.receive(b);}
  void hb(boolean armed,int mode)throws Exception{byte[]b=p(0);le(b).putInt(0,mode);b[4]=2;b[5]=3;b[6]=(byte)(armed?128:0);b[7]=4;b[8]=3;emit(0,b);}
  void home()throws Exception{byte[]b=p(242);le(b).putInt(0,108540000).putInt(4,1068070000).putInt(8,homeAlt);emit(242,b);}
  void land(int state)throws Exception{byte[]b=p(245);b[1]=(byte)state;emit(245,b);}
  void pos(int rel)throws Exception{byte[]b=p(33);le(b).putInt(0,(int)(c.n/1000000)).putInt(4,108540000).putInt(8,1068070000).putInt(12,homeAlt+rel).putInt(16,rel);emit(33,b);}
  void health()throws Exception{byte[]b=p(1);int mask=1|2|4|8|32|2097152|(1<<28);le(b).putInt(0,mask).putInt(4,mask).putInt(8,mask).putShort(14,(short)24000);b[30]=80;emit(1,b);b=p(24);le(b).putShort(20,(short)100);b[28]=3;b[29]=12;emit(24,b);b=p(193);le(b).putShort(Dialect95.at(193,"flags"),(short)55);emit(193,b);}
  void ground()throws Exception{hb(false,4);byte[]v=p(148);le(v).putInt(Dialect95.at(148,"flight_sw_version"),67568127);System.arraycopy("dbe79216".getBytes("US-ASCII"),0,v,Dialect95.at(148,"flight_custom_version"),8);emit(148,v);for(Map.Entry<String,int[]>e:ProfileFixture.specs().entrySet()){byte[]b=p(22);le(b).putInt(0,e.getValue()[1]);byte[]k=e.getKey().getBytes("US-ASCII");System.arraycopy(k,0,b,8,k.length);b[24]=(byte)e.getValue()[0];emit(22,b);}home();land(1);health();pos(0);}
  void input(double pitch,int pointers,boolean release)throws Exception{long up=c.n-100000000L;int action=release?1:pointers==0?-1:2;long lastMotion=action==-1?0:up;s.input(new ControlAuthority.Input(context,SOURCE,"ANDROID_UPTIME_NS_SAMPLER",PROV,++inputseq,up,c.n,lastMotion,new double[]{0,pitch,0,0},pointers,action,release));}
  void action(String action,String hash)throws Exception{s.action(action,action+"-"+c.n,hash,c.n);}
  void startPilot()throws Exception{
   input(0,0,false);action("CONSENT",null);action("ARM",null);c.n=1100000000L;hb(true,4);input(0,0,false);c.n=1200000000L;homeAlt=10012;home();input(0,0,false);Map<?,?> flight=(Map<?,?>)s.snapshot().get("flight");action("CONFIRM_HOME",(String)flight.get("homeHash"));action("TAKEOFF",null);
   for(int t=1250;t<=2350;t+=50){c.n=t*1000000L;input(0,0,false);if(t%200==50){hb(true,4);land(2);health();home();pos(3000);}}
   action("LOITER",null);c.n=2360000000L;hb(true,5);land(2);health();home();pos(3000);
  }
  void close(){try{s.close("QA_CLOSE",true);}catch(Exception e){s.fail("QA_CLOSE_FAILURE",true);}try{journal.close();}catch(Exception ignored){}}
 }
 static int message(byte[]wire){return(wire[7]&255)|(wire[8]&255)<<8|(wire[9]&255)<<16;}static byte[]data(byte[]wire){return Arrays.copyOfRange(wire,10,wire.length-2);}static int u16(byte[]p,int o){return(p[o]&255)|(p[o+1]&255)<<8;}
 public static void main(String[]args)throws Exception{root=new File(args[0]);check(root.mkdir(),"exclusive fixture");
  test("S01_CONTINUOUS_FRESH_INPUT_TO_WIRE",()->{F f=new F("continuous",20000000000L);try{f.startPilot();int begin=f.sent.size();for(int i=0;i<5;i++){f.c.n+=50000000;f.input(.4,1,false);}check(f.sent.size()-begin==5,"not one wire per fresh input");for(byte[]wire:f.sent.subList(begin,f.sent.size())){check(message(wire)==70,"wrong message");byte[]b=data(wire);check(u16(b,0)==1500&&u16(b,2)==1450&&u16(b,4)==1500&&b[16]==42&&b[17]==1,"axis or target");}check(lines(f.dir).contains("CONTROL_INPUT_WIRE_BINDING"),"binding absent");}finally{f.close();}});
  test("S02_EXPIRED_INPUT_FINITE_BRAKE_THEN_NEUTRAL_RELEASE",()->{F f=new F("release",20000000000L);try{f.startPilot();f.c.n+=50000000;f.input(.4,1,false);int count=f.sent.size();f.c.n+=201000000L;f.s.tick();check(f.sent.size()==count+1,"brake not once");byte[]b=data(f.sent.get(count));check(message(f.sent.get(count))==76&&u16(b,28)==176&&le(b).getFloat(4)==17,"no BRAKE17");f.s.tick();check(f.sent.size()==count+1,"brake retried");f.c.n+=1000000;f.hb(true,17);check(f.sent.size()==count+3,"not finite3");byte[]neutral=data(f.sent.get(count+1)),release=data(f.sent.get(count+2));check(u16(neutral,0)==1500&&u16(neutral,2)==1500&&u16(neutral,4)==1500,"neutral");for(int o=0;o<16;o+=2)check(u16(release,o)==0,"releasech1..8");for(int o=18;o<38;o+=2)check(u16(release,o)==65534,"releaseextensions");Map<?,?>input=(Map<?,?>)f.s.snapshot().get("input");check(Boolean.FALSE.equals(input.get("consent")),"authority restored");f.s.tick();check(f.sent.size()==count+3,"extra cleanup packets");}finally{f.close();}});
  test("S03_FSYNC_DELAY_EXPIRES_INPUT_BEFORE_SOCKET",()->{F f=new F("stall",20000000000L);try{f.startPilot();int n=f.sent.size();f.c.n+=50000000;f.stallIntent=true;denied(()->f.input(.4,1,false),"stale callback sent");check(f.sent.size()==n,"socket called after stall");check(Boolean.TRUE.equals(f.journal.snapshot().get("failed")),"unknown not fenced");check(lines(f.dir).contains("TX_UNKNOWN"),"unknown outcome absent");}finally{f.close();}});
  test("S04_UNKNOWN_SEND_NO_RETRY",()->{F f=new F("unknown",20000000000L);try{f.startPilot();int n=f.sent.size();f.c.n+=50000000;f.failSend=true;denied(()->f.input(.4,1,false),"send fault accepted");check(f.sent.size()==n,"unknown counted as sent");check(Boolean.TRUE.equals(f.journal.snapshot().get("failed")),"unknown no poison");check(!f.s.actionRefusalRecoverable(new IOException("QA_UNKNOWN")),"unknown deemed retryable");}finally{f.close();}});
  test("S05_EXPIRED_RUN_REFUSES_AT_WIRE",()->{F f=new F("deadline",100000000L);try{f.input(0,0,false);f.action("CONSENT",null);f.c.n+=101000000L;int n=f.sent.size();denied(()->f.action("GUIDED",null),"run deadline ignored");check(f.sent.size()==n,"wire after deadline");}finally{f.close();}});
  test("S06_STALE_HEARTBEAT_BLOCKS_NORMAL_RC",()->{F f=new F("stale-hb",20000000000L);try{f.startPilot();f.c.n+=1600000000L;int n=f.sent.size();denied(()->f.input(.4,1,false),"stale lease/heartbeat accepted");check(f.sent.size()==n,"normal RC after stale observations");}finally{f.close();}});
  test("S07_FRESH_PRODUCER_CANNOT_OVERRIDE_STALE_AP_HEARTBEAT",()->{F f=new F("fresh-input-stale-ap",20000000000L);try{f.startPilot();for(int i=0;i<28;i++){f.c.n+=50000000;f.input(0,0,false);}f.c.n+=150000000;int n=f.sent.size();denied(()->f.input(.4,1,false),"fresh input revived stale AP readiness");check(f.sent.size()==n,"normal RC after old AP heartbeat");}finally{f.close();}});
  test("S08_OWNER_IO_LOOP_STALL_REFUSES_FRESH_INPUT",()->{F f=new F("io-loop",20000000000L);try{f.startPilot();f.s.observeLoop(f.c.n);f.c.n+=501000000;int n=f.sent.size();denied(()->f.input(.4,1,false),"fresh producer bypassed stalled owner");check(f.sent.size()==n,"wire after sustained owner gap");check(String.valueOf(f.s.snapshot().get("firstFailure")).contains("CONTROL_LOOP_IO_GAP"),"loop gap not retained");}finally{f.close();}});
  test("S09_STALE_RX_RETAINED_BUT_CANNOT_REFRESH_PREFLIGHT",()->{F f=new F("stale-rx",20000000000L);try{long receipt=f.c.n;byte[]b=Mavlink.packet(0,new byte[9],f.apseq++);f.c.n+=201000000;denied(()->f.s.receive(b,receipt),"stale RX applied");check(lines(f.dir).contains("AP_RX_APPLY_REFUSED"),"refusal absent");check(lines(f.dir).contains("\"base64\":\""+Base64.getEncoder().encodeToString(b)+"\""),"consumed bytes not retained");check("RAW_RX_APPLY_IO_GAP".equals(f.s.snapshot().get("firstFailure")),"failure not retained");}finally{f.close();}});
  System.out.println(Values.json(Values.map("format","aeris-independent-control-session-qa","results",results,"scope","PURE_JVM_REAL_FILESYSTEM_MOCK_AP_AND_SOCKET")));
 }
}
